import * as T from './three.js';
const geometries=new Map();function geometry(key,create){if(!geometries.has(key))geometries.set(key,create());return geometries.get(key)}
const cache=new Map();export function material(c){if(!cache.has(c))cache.set(c,new T.MeshStandardMaterial({color:c,roughness:.8}));return cache.get(c)}
export function box(g,w,h,d,c,x=0,y=0,z=0,r=0){const m=new T.Mesh(geometry(`box:${w}:${h}:${d}`,()=>new T.BoxGeometry(w,h,d)),material(c));m.position.set(x,y,z);m.rotation.y=r;m.castShadow=true;m.receiveShadow=true;g.add(m);return m}
export function cylinder(g,rt,rb,h,c,x=0,y=0,z=0,n=16){const m=new T.Mesh(geometry(`cylinder:${rt}:${rb}:${h}:${n}`,()=>new T.CylinderGeometry(rt,rb,h,n)),material(c));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;g.add(m);return m}
export function sphere(g,r,c,x,y,z,sx=1,sy=1,sz=1){const m=new T.Mesh(geometry(`sphere:${r}`,()=>new T.IcosahedronGeometry(r,1)),material(c));m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;g.add(m);return m}
export function sign(g,text,w,h,x,y,z,bg='#f5eedc',fg='#35594b'){const c=document.createElement('canvas');c.width=1024;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,1024,256);ctx.fillStyle=fg;ctx.font='bold '+Math.min(115,1500/text.length)+'px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,512,128);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;const m=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshStandardMaterial({map:tex,roughness:.9}));m.position.set(x,y,z);g.add(m);return m}
export function tree(g,x,z,s=1,type=0){const t=new T.Group();t.position.set(x,0,z);t.scale.setScalar(s);g.add(t);cylinder(t,.16,.27,2.5,'#92724f',0,1.2,0,7);if(type===1){for(let j=0;j<3;j++)cylinder(t,0,1.7-j*.3,2,'#62865e',0,2.2+j*.9,0,7)}else{sphere(t,1.5,'#8ca36b',0,3,0,1,.85,1);sphere(t,1.1,'#a0b77a',.6,3.7,.1);sphere(t,1.1,'#708e60',-.8,2.6,.3)}return t}
function window(g,x,y,z,w=1.4,h=1.5){box(g,w+.2,h+.2,.12,'#f4ead5',x,y,z);box(g,w,h,.15,'#76a4ad',x,y,z+.08);box(g,.07,h,.2,'#efeadb',x,y,z+.16);box(g,w+.35,.12,.4,'#d6ceb9',x,y-h/2,z+.1)}
function bench(g,x,z,r=0){const b=new T.Group();b.position.set(x,0,z);b.rotation.y=r;g.add(b);for(const xx of [-1,1]){box(b,.12,.8,.15,'#3e6254',xx,.4,0);box(b,.12,.8,.15,'#3e6254',xx,.4,.7)}for(let i=0;i<3;i++)box(b,2.6,.1,.23,'#b59061',0,.8,i*.25);for(let i=0;i<2;i++)box(b,2.6,.22,.12,'#b59061',0,1.1+i*.28,-.08)}
export function lamp(g,x,z){cylinder(g,.07,.12,4.6,'#557065',x,2.3,z,8);box(g,1.2,.12,.12,'#557065',x+.45,4.6,z);const bulb=box(g,.65,.12,.45,'#ffe4a1',x+.9,4.48,z);bulb.material=new T.MeshStandardMaterial({color:'#fff0c3',emissive:'#ffd183',emissiveIntensity:.4});return bulb}
function planter(g,x,z){box(g,1.5,.55,1,'#c9b795',x,.28,z);sphere(g,.65,'#829b5e',x,.8,z,1,.7,.7);for(let j=0;j<4;j++)sphere(g,.11,j%2?'#eeb37b':'#e6d6ba',x-.4+j*.25,1.1,z)}
function flag(g,x,z,c,animated){cylinder(g,.04,.06,5.8,'#7d8d79',x,2.9,z,6);const cloth=box(g,1.5,1,.05,c,x+.75,5,z);animated.push({mesh:cloth,type:'flag',phase:x});}
export function location(scene,p,animated){const g=new T.Group();g.position.set(p.x,0,p.z);scene.add(g);box(g,15,.3,12,'#d7cfb6',0,.08,0);box(g,14.6,.1,11.6,'#eee4cd',0,.28,0);for(let i=0;i<6;i++)box(g,1.8,.07,1.2,'#e5dcc5',0,.1,7+i*1.35);p.target={x:p.x,z:p.z+11};
if(p.id==='arenix'){
box(g,11,.08,7,'#799b80',0,.4,-.2);box(g,8,.05,5.5,'#d5ad7c',0,.46,-.2);for(const xx of [-4,4])box(g,.08,.03,5.5,'#faf2d3',xx,.5,-.2);for(const zz of [-2.95,-.2,2.55])box(g,8,.03,.08,'#faf2d3',0,.5,zz);for(const zz of [-3,2.6])cylinder(g,.06,.06,1.9,'#3c685a',0,1.4,zz,8);for(let j=0;j<10;j++)box(g,.025,1,.025,'#f0ead2',0,1.4,-2.9+j*.6);for(let j=0;j<5;j++)box(g,.035,.025,5.5,'#f0ead2',0,.95+j*.23,-.2);for(let x=-6;x<=6;x+=2){box(g,.06,2.6,.06,'#5b7864',x,1.6,-4.3);box(g,.06,2.6,.06,'#5b7864',x,1.6,4)}for(let y=.7;y<3;y+=.5){box(g,12,.03,.03,'#809687',0,y,-4.3)}box(g,5,.1,1.2,'#a87a52',0,.7,-5);box(g,5,.1,1.2,'#a87a52',0,1.1,-5.4);sphere(g,.3,'#e7ce76',2,.8,1.5);flag(g,-6,-4,'#dc9868',animated);flag(g,6,-4,'#87a679',animated);sign(g,'ARENIX',5,1.1,0,3.6,-4.2);for(const x of [-5.5,5.5]){cylinder(g,.08,.1,5,'#57786b',x,2.5,4);box(g,1.2,.3,.5,'#f2e2b4',x,5,4)}
}else if(p.id==='mapa'){
box(g,9,4.8,6,'#e2c495',0,2.75,-1);box(g,10,.35,7,'#b77d59',0,5.3,-1);box(g,4,1.1,2,'#ddc79d',0,5.8,-1);sign(g,'UFC · RUSSAS',5,.8,0,4.4,2.06);for(const x of [-3,0,3])window(g,x,2.9,2.08,1.6,1.5);for(const x of [-4,4])box(g,.45,3.8,.45,'#faf0d7',x,2,2.8);box(g,9,.3,1.5,'#c98f67',0,4,2.8);for(let i=0;i<3;i++)box(g,5+i*.5,.18,1+i*.5,'#d7c5a5',0,.5-i*.1,3.2+i*.1);const book=new T.Group();g.add(book);book.position.set(-5.5,.8,4);box(book,1,.6,.8,'#be795b');box(book,1.1,.12,.85,'#37665b',0,.38,0);bench(g,5,4);flag(g,-6,0,'#6f9366',animated);planter(g,-4,4);
}else if(p.id==='pet'){
cylinder(g,3.5,3.8,.3,'#d4c2ac',0,.5,0,40);cylinder(g,2,2.3,.5,'#b4a2b4',0,.9,0,8);box(g,1.7,1.2,1.7,'#9a87a6',0,1.7,0);cylinder(g,.18,.35,1.1,'#d6ac59',0,2.7,0,12);cylinder(g,1.1,.35,1.3,'#e3bb69',0,3.6,0,18);cylinder(g,1.15,1.15,.15,'#f1d287',0,4.3,0,20);for(const x of [-1,1]){const tor=new T.Mesh(new T.TorusGeometry(.55,.12,8,16),material('#d8ad5d'));tor.position.set(x,3.65,0);g.add(tor)}sign(g,'PET / LEVEL UP',4.2,.75,0,1.8,1);bench(g,-5,2,Math.PI/2);bench(g,5,2,-Math.PI/2);flag(g,-5,-4,'#b49aca',animated);flag(g,5,-4,'#dab273',animated);for(let i=0;i<8;i++)sphere(g,.16,'#d5b16c',Math.cos(i)*2.7,.9,Math.sin(i)*2.7);
}else if(p.id==='orto'){
box(g,8,4,6,'#e8ece0',0,2.4,-1);box(g,8.8,.35,6.8,'#6d9d91',0,4.6,-1);box(g,9,.4,1.6,'#82b2a4',0,3.2,2.5);for(const x of [-2.6,2.6])window(g,x,1.9,2.08,1.7,1.8);box(g,1.6,2.3,.15,'#5b8f95',0,1.55,2.1);box(g,.08,2.2,.16,'#eeeada',0,1.55,2.2);sign(g,'ORTOBASE',4,.7,0,3.85,2.1);box(g,1.1,.25,.15,'#6c9d85',0,5.8,-.8);box(g,.25,1.1,.15,'#6c9d85',0,5.8,-.8);box(g,2,1.6,.2,'#f1eadb',0,5.6,-1);planter(g,-4.7,3);planter(g,4.7,3);bench(g,-5,-2,Math.PI/2);
}else if(p.id==='food'){
box(g,8,3.8,6,'#dfab80',0,2.3,-1);box(g,8.8,.45,6.8,'#b96e50',0,4.4,-1);sign(g,'BYTE & BITE',5.5,.8,0,3.7,2.1,'#486b55','#fff0d7');for(const x of [-2.5,2.5])window(g,x,2,2.08,2,1.6);box(g,1.3,2.4,.1,'#688d79',0,1.55,2.1);for(let i=0;i<10;i++){const aw=box(g,.82,.12,2,i%2?'#f6e7c9':'#bc654e',-3.7+i*.82,3.2,3.2);aw.rotation.x=.18;box(g,.82,.4,.1,i%2?'#f6e7c9':'#bc654e',-3.7+i*.82,2.8,4.2)}for(const x of [-4,4]){cylinder(g,.8,.8,.12,'#a77850',x,1,5);cylinder(g,.07,.12,.9,'#4b6b54',x,.5,5);for(const z of [4,6]){cylinder(g,.35,.35,.12,'#b18657',x,.55,z);cylinder(g,.06,.09,.5,'#51634d',x,.25,z)}cylinder(g,0,1.7,1,'#e1b96f',x,3.4,5,8);cylinder(g,.045,.045,3,'#927451',x,1.8,5)}const burger=new T.Group();g.add(burger);burger.position.set(0,5.6,-1);sphere(burger,1,'#dbac61',0,.2,0,1,.45,1);cylinder(burger,1,1,.16,'#668c4b',0,-.1,0);cylinder(burger,.95,.95,.25,'#815442',0,-.3,0);sphere(burger,1,'#d5a259',0,-.55,0,1,.2,1);
}else{
box(g,6,3.5,5,'#a7b487',0,2.1,-1);const roof=new T.Mesh(new T.ConeGeometry(5.1,2,4),material('#7b8e69'));roof.rotation.y=Math.PI/4;roof.position.set(0,4.7,-1);roof.scale.z=.9;g.add(roof);window(g,-1.6,2,1.55,1.5,1.5);box(g,1.5,2.5,.15,'#687c5a',1.5,1.55,1.6);sign(g,'ACHADOS & PERDIDOS',5.8,.7,0,3.4,1.6);for(let i=0;i<3;i++){box(g,1,.9,1,'#bc986d',-4+i*.3,.8+i*.7,2);box(g,.1,.9,1.02,'#ddc9a2',-4+i*.3,.8+i*.7,2)}box(g,.8,1.1,.45,'#d48865',4,.9,2);box(g,.5,.45,.15,'#bc7052',4,.7,2.3);bench(g,0,4);}
// Destination marker and small roadside plaque.
const marker=cylinder(g,1.9,1.9,.035,'#fff2d4',0,.12,11,48);const ring=new T.Mesh(new T.RingGeometry(1.65,1.8,48),new T.MeshBasicMaterial({color:p.color,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.set(0,.15,11);g.add(ring);const arrow=sign(g,'P',1,1,0,.17,11);arrow.rotation.x=-Math.PI/2;box(g,.1,1.5,.1,'#7d8064',4,.8,7.5);sign(g,p.name.toUpperCase(),3.5,.65,4,1.8,7.6);p.group=g;return g}
